import{_ as s}from"./chunks/1c4467b41961bde0fa1aee34061b93d9.B03u6GuX.js";import{_ as a}from"./chunks/19d892913f88a70cbf47536b9fb10cf3.JrcQ8Gbe.js";import{_ as e,c as n,a2 as r,o}from"./chunks/framework.BnrAgU0Y.js";const l="/bllm/assets/fcd87f4995f18c3ac77d94dc39fbcfd1.Dp-dwCe6.png",A=JSON.parse('{"title":"快速入门","description":"快速入门","frontmatter":{"title":"快速入门","description":"快速入门","layout":"doc"},"headers":[],"relativePath":"langflow/get-started-quickstart.md","filePath":"langflow/get-started-quickstart.md"}'),i={name:"langflow/get-started-quickstart.md"};function p(g,t,c,d,h,m){return o(),n("div",null,t[0]||(t[0]=[r('<h1 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to &quot;快速入门&quot;">​</a></h1><p>通过构建一个基于OpenAI的聊天机器人应用来了解Langflow。在构建完聊天机器人后，添加检索增强生成（Retrieval Augmented Generation，RAG），以便使用自己的数据进行聊天。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li><a href="https://platform.openai.com/" target="_blank" rel="noreferrer">OpenAI API 密钥</a></li><li><a href="https://docs.datastax.com/en/astra-db-serverless/get-started/quickstart.html" target="_blank" rel="noreferrer">Astra DB 向量数据库</a> ，包括： <ul><li>AstraDB 应用令牌</li><li><a href="https://docs.datastax.com/en/astra-db-serverless/databases/manage-collections.html#create-collection" target="_blank" rel="noreferrer">Astra 中的一个集合</a></li></ul></li></ul><h2 id="打开-langflow-并开始一个新项目" tabindex="-1">打开 Langflow 并开始一个新项目 <a class="header-anchor" href="#打开-langflow-并开始一个新项目" aria-label="Permalink to &quot;打开 Langflow 并开始一个新项目&quot;">​</a></h2><ol><li>在 Langflow 仪表板中，点击 <strong>New Flow</strong>，然后选择 <strong>Blank Flow</strong>。此时会打开一个空白工作区，您可以在这里构建您的流程。</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果您不想创建一个空白流程，可以点击 <strong>New Flow</strong>，然后选择 <strong>Basic Prompting</strong> 来启动一个预构建的流程。 继续前往<a href="#run-basic-prompting-flow">运行基本提示流程</a>。</p></div><ol start="2"><li><p>选择 <strong>Basic Prompting</strong>。</p></li><li><p><strong>Basic Prompting</strong> 流程已创建。</p></li></ol><h2 id="构建基本提示流程" tabindex="-1">构建基本提示流程 <a class="header-anchor" href="#构建基本提示流程" aria-label="Permalink to &quot;构建基本提示流程&quot;">​</a></h2><p>基本提示流程完成后将如下所示：</p><p><img src="'+s+'" alt=""></p><p>要构建<strong>基础提示</strong>流程，请按照以下步骤操作：</p><ol><li><p>点击<strong>输入</strong>，选择<strong>聊天输入</strong>组件，然后将其拖动到画布上。 <strong>聊天输入</strong>组件接受用户输入到聊天中。<a href="https://example.com/components-io#chat-input" target="_blank" rel="noreferrer">聊天输入</a></p></li><li><p>点击<strong>提示</strong>，选择<strong>提示</strong>组件，然后将其拖动到画布上。 <strong>提示</strong>组件将用户输入与用户定义的提示结合在一起。<a href="https://example.com/components-prompts" target="_blank" rel="noreferrer">提示</a></p></li><li><p>点击<strong>输出</strong>，选择<strong>聊天输出</strong>组件，然后将其拖动到画布上。 <strong>聊天输出</strong>组件将流程的输出打印到聊天中。<a href="https://example.com/components-io#chat-output" target="_blank" rel="noreferrer">聊天输出</a></p></li><li><p>点击<strong>模型</strong>，选择<strong>OpenAI</strong>组件，然后将其拖动到画布上。 <strong>OpenAI</strong>模型组件将用户输入和提示发送到OpenAI API并接收响应。<a href="https://example.com/components-models#openai" target="_blank" rel="noreferrer">OpenAI</a></p></li></ol><p>现在，你应该有一个看起来像这样的流程：</p><p><img src="'+l+'" alt=""></p><p>如果组件之间没有连接，它们将无法相互交互。您希望数据通过组件之间的连接从**聊天输入**传递到**聊天输出**。每个组件在左侧接受输入，并在右侧发送输出。将鼠标悬停在连接端口上，以查看组件接受的数据类型。有关组件输入和输出的更多信息，请参见[组件概述](/concepts-components)。</p><ol start="5"><li>要将<strong>聊天输入</strong>组件连接到 OpenAI 模型组件，请点击并拖动一条线从蓝色的<strong>消息</strong>端口到 OpenAI 模型组件的<strong>输入</strong>端口。</li><li>要将<strong>提示</strong>组件连接到 OpenAI 模型组件，请点击并拖动一条线从蓝色的<strong>提示消息</strong>端口到 OpenAI 模型组件的<strong>系统消息</strong>端口。</li><li>要将<strong>OpenAI</strong>模型组件连接到<strong>聊天输出</strong>，请点击并拖动一条线从蓝色的<strong>文本</strong>端口到<strong>聊天输出</strong>组件的<strong>文本</strong>端口。</li></ol><p>您完成的基本提示流应如下所示：</p><p><img src="'+s+`" alt=""></p><h3 id="运行基本提示流" tabindex="-1">运行基本提示流 <a class="header-anchor" href="#运行基本提示流" aria-label="Permalink to &quot;运行基本提示流&quot;">​</a></h3><p>将您的 OpenAI API 密钥添加到 OpenAI 模型组件中，并在提示组件中添加提示，指导模型如何响应。</p><ol><li><p><strong>将您的凭据添加到 OpenAI 组件中。</strong> 完成这些字段最快的方法是使用 Langflow 的<a href="https://link-to-global-variables" target="_blank" rel="noreferrer">全局变量</a>。</p><ol><li>在 OpenAI 组件的 OpenAI API 密钥字段中，点击 <strong>Globe</strong> 按钮，然后点击 <strong>Add New Variable</strong>。或者，点击右上角的用户名，然后点击 <strong>Settings</strong>、<strong>Global Variables</strong>，再点击 <strong>Add New</strong>。</li><li>为您的变量命名。在值字段中粘贴您的 OpenAI API 密钥（sk-…​）。</li><li>在 <strong>Apply To Fields</strong> 字段中，选择 OpenAI API 密钥字段，以将此变量应用于所有 OpenAI Embeddings 组件。</li></ol></li><li><p><strong>要向</strong> <code>Prompt</code> <strong>组件添加提示，点击</strong> <code>Template</code> <strong>字段，然后输入您的提示。</strong> 提示指导机器人的输入响应。如果您不确定提示内容，可以使用 <code>Answer the user as if you were a GenAI expert, enthusiastic about helping them get started building something fresh.</code></p></li><li><p>点击 <strong>Playground</strong> 启动聊天会话。</p></li><li><p>输入查询，然后确保机器人根据您在 <code>Prompt</code> 组件中设置的提示进行响应。</p></li></ol><p>您已成功使用 OpenAI 在 Langflow 工作区创建了一个聊天机器人应用程序。</p><h2 id="添加向量rag到您的应用程序" tabindex="-1">添加向量RAG到您的应用程序 <a class="header-anchor" href="#添加向量rag到您的应用程序" aria-label="Permalink to &quot;添加向量RAG到您的应用程序&quot;">​</a></h2><p>您使用Langflow创建了一个聊天机器人应用程序，但让我们尝试做一个实验。</p><ol><li>向机器人提问：<code>2024年获得奥斯卡最佳影片奖的是谁？</code></li><li>机器人的回答类似于这样：</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m sorry, but I don&#39;t have information on events or awards that occurred after</span></span>
<span class="line"><span>October 2023, including the Oscars in 2024.</span></span>
<span class="line"><span>You may want to check the latest news or the official Oscars website</span></span>
<span class="line"><span>for the most current information.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>嗯，这有点遗憾，但您可以通过<strong>检索增强生成</strong>（<strong>Retrieval Augmented Generation</strong>，简称<strong>RAG</strong>）加载更多最新的数据。</p><p>向量RAG允许您加载自己的数据并与之对话，为您的聊天机器人应用程序解锁更广泛的可能性。</p><h2 id="添加向量-rag-与-astra-db-组件" tabindex="-1">添加向量 RAG 与 Astra DB 组件 <a class="header-anchor" href="#添加向量-rag-与-astra-db-组件" aria-label="Permalink to &quot;添加向量 RAG 与 Astra DB 组件&quot;">​</a></h2><p>在基本的提示流基础上，通过 <strong>Astra DB 向量存储</strong> 组件将向量 RAG 添加到您的聊天机器人应用程序中。</p><p>用 <strong>Astra DB</strong> 组件作为向量存储，将文档摄取添加到您的基本提示流中。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果您不想创建一个空白流，请点击 <strong>New Flow</strong>，然后选择 <strong>Vector RAG</strong> 来选择一个预构建的流。</p></div><p>添加向量 RAG 到基本提示流后，完成后看起来会是这样的：</p><p><img src="`+a+'" alt=""></p><p>要构建流程，请按照以下步骤操作：</p><ol><li><p>通过双击连接线将 <strong>Chat Input</strong> 组件与 <strong>OpenAI</strong> 组件断开。</p></li><li><p>点击 <strong>Vector Stores</strong>，选择 <strong>Astra DB</strong> 组件，然后将其拖动到画布上。<a href="/components-vector-stores#astra-db-vector-store">Astra DB vector store</a> 组件连接到你的 <strong>Astra DB</strong> 数据库。</p></li><li><p>点击 <strong>Data</strong>，选择 <strong>File</strong> 组件，然后将其拖动到画布上。<a href="/components-data#file">File</a> 组件从你的本地计算机加载文件。</p></li><li><p>点击 <strong>Processing</strong>，选择 <strong>Split Text</strong> 组件，然后将其拖动到画布上。<a href="/components-processing#split-text">Split Text</a> 组件将加载的文本拆分为更小的块。</p></li><li><p>点击 <strong>Processing</strong>，选择 <strong>Parse Data</strong> 组件，然后将其拖动到画布上。<a href="/components-processing#data-to-message">Data to Message</a> 组件将 <strong>Astra DB</strong> 组件中的数据转换为纯文本。</p></li><li><p>点击 <strong>Embeddings</strong>，选择 <strong>OpenAI Embeddings</strong> 组件，然后将其拖动到画布上。<a href="/components-embedding-models#openai-embeddings">OpenAI Embeddings</a> 组件为用户输入生成嵌入，这些嵌入与数据库中的向量数据进行比较。</p></li><li><p>将新组件连接到现有流程，使你的流程看起来如下所示：</p></li></ol><p><img src="'+a+`" alt=""></p><h3 id="_8-配置-astra-db-组件" tabindex="-1">8. 配置 <strong>Astra DB</strong> 组件 <a class="header-anchor" href="#_8-配置-astra-db-组件" aria-label="Permalink to &quot;8. 配置 **Astra DB** 组件&quot;">​</a></h3><ol><li>在 <strong>Astra DB Application Token</strong> 字段中，添加您的 <strong>Astra DB</strong> 应用程序令牌。该组件将连接到您的数据库，并使用现有数据库和集合填充菜单。</li><li>选择您的 <strong>Database</strong>。</li><li>选择您的 <strong>Collection</strong>。集合是在您的 <a href="https://astra.datastax.com" target="_blank" rel="noreferrer">Astra DB 部署</a> 中创建的，用于存储向量数据。如果您没有集合，请参阅 <a href="https://docs.datastax.com/en/astra-db-serverless/databases/manage-collections.html#create-collection" target="_blank" rel="noreferrer">DataStax Astra DB 无服务器文档</a>。</li><li>选择 <strong>Embedding Model</strong> 来引入您自己的嵌入模型，这与连接的 <strong>OpenAI Embeddings</strong> 组件相关。<strong>Dimensions</strong> 值必须与您集合的维度匹配。此值可以在您的 <a href="https://astra.datastax.com" target="_blank" rel="noreferrer">Astra DB 部署</a> 的 <strong>Collection</strong> 中找到。</li></ol><p>如果您使用了 Langflow 的 <strong>Global Variables</strong>（全局变量）功能，RAG 应用程序流程组件已经配置了必要的凭证。</p><h3 id="运行包含检索上下文的聊天机器人" tabindex="-1">运行包含检索上下文的聊天机器人 <a class="header-anchor" href="#运行包含检索上下文的聊天机器人" aria-label="Permalink to &quot;运行包含检索上下文的聊天机器人&quot;">​</a></h3><ol><li>修改 <strong>Prompt</strong> 组件以包含用于 <code>&lt;code&gt;{user_question}&lt;/code&gt;</code> 和 <code>&lt;code&gt;{context}&lt;/code&gt;</code> 的变量。 <code>&lt;code&gt;{context}&lt;/code&gt;</code> 变量为机器人提供了额外的上下文，用于回答 <code>&lt;code&gt;{user_question}&lt;/code&gt;</code>，超出 LLM 已知的范围。</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Given the context</span></span>
<span class="line"><span>{context}</span></span>
<span class="line"><span>Answer the question</span></span>
<span class="line"><span>{user_question}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ol start="2"><li>在 <strong>File</strong> 组件中，从本地机器上传一个文本文件，数据将被导入到 <strong>Astra DB</strong> 组件数据库中。此示例上传了一个关于奥斯卡获奖者的最新 CSV 文件。</li><li>点击 <strong>Playground</strong> 开始聊天会话。</li><li>向机器人提问：<code>Who won the Oscar in 2024 for best movie?</code></li><li>机器人的回答应类似于以下内容：</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The Oscar for Best Picture in 2024 was awarded to &quot;Oppenheimer,&quot;</span></span>
<span class="line"><span>produced by Emma Thomas, Charles Roven, and Christopher Nolan.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>通过添加 <strong>Astra DB</strong> 向量存储，您的聊天机器人已经进入了 2024 年。您已成功使用 <strong>Astra DB</strong> 组件将 RAG 添加到您的聊天机器人应用程序中。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>虽然这个示例使用了电影数据，但 RAG（可回忆生成）模式可以应用于您想要加载和对话的任何数据。</p><p>让 <strong>Astra DB</strong> 数据库成为 <a href="./agents-overview.html">Agents</a> 用于决策的“大脑”。</p><p>将这个流程公开为 <a href="./concepts-api.html">API</a>，从您的外部应用程序中调用它。</p><p>关于 <strong>Astra DB</strong> 组件的更多信息，请参见 <a href="./components-vector-stores.html#astra-db-vector-store">Astra DB 向量存储</a>。</p>`,52)]))}const k=e(i,[["render",p]]);export{A as __pageData,k as default};
